<script setup lang="ts">
import{onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import AppButton from'../components/ui/AppButton.vue';import AppEmptyState from'../components/ui/AppEmptyState.vue';import AppInput from'../components/ui/AppInput.vue';import{apiRequest}from'../services/api';
const route=useRoute(),router=useRouter(),q=ref(String(route.query.q??'')),loading=ref(false),error=ref(''),result=ref<{recipes:Array<{id:string;name:string}>;ingredients:Array<{id:string;name:string}>;stores:Array<{id:string;name:string}>;records:Array<{id:string;recordDate:string;notes:string|null}>}>({recipes:[],ingredients:[],stores:[],records:[]});
async function search(){if(!q.value.trim())return;loading.value=true;error.value='';try{await router.replace({query:{q:q.value}});result.value=await apiRequest('/search',{query:{q:q.value}})}catch(e){error.value=e instanceof Error?e.message:'搜索失败'}finally{loading.value=false}}
const total=()=>Object.values(result.value).reduce((n,x)=>n+x.length,0);watch(()=>route.query.q,()=>{q.value=String(route.query.q??'');void search()});onMounted(()=>{if(q.value)void search()});
</script>
<template><section class="business-page"><header class="business-hero"><div><p class="business-eyebrow">Global search</p><h1>全局搜索</h1><p>同时查找菜谱、结构化食材、店铺和饮食记录。</p></div></header><form class="business-toolbar app-card" @submit.prevent="search"><AppInput v-model="q" label="关键词" autofocus/><AppButton type="submit" :loading="loading">搜索</AppButton></form><p v-if="error" class="business-conflict">{{error}}</p><AppEmptyState v-else-if="!total()&&!loading" title="没有找到结果" description="换一个菜名、食材、店铺或备注关键词试试。"/><div v-else class="business-grid"><section v-for="(items,key) in result" :key="key" class="app-card"><h2>{{({recipes:'菜谱',ingredients:'食材',stores:'店铺',records:'记录'} as Record<string,string>)[key]}}</h2><p v-for="item in items" :key="item.id">{{'name' in item?item.name:`${item.recordDate} · ${item.notes||'饮食记录'}`}}</p><p v-if="!items.length">暂无</p></section></div></section></template>
